import { CommonModule } from '@angular/common';
import { Component, OnInit, OnDestroy, AfterViewInit, ViewChild, ElementRef, inject } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { RouterModule, Router } from '@angular/router';
import { Chart, registerables } from 'chart.js';
import { AnalyticsService } from '../../../../services/reports/analytics.service';
import { RevenueAnalytics } from '../../../../models/reports/analytics.model';

Chart.register(...registerables);

@Component({
  selector: 'app-revenue-reports',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterModule],
  templateUrl: './revenue-reports.component.html',
  styleUrls: ['./revenue-reports.component.css']
})
export class RevenueReportsComponent implements OnInit, AfterViewInit, OnDestroy {

  @ViewChild('dailyTrendChart') dailyTrendChartRef!: ElementRef<HTMLCanvasElement>;
  @ViewChild('monthlyTrendChart') monthlyTrendChartRef!: ElementRef<HTMLCanvasElement>;
  @ViewChild('paymentMethodsChart') paymentMethodsChartRef!: ElementRef<HTMLCanvasElement>;
  @ViewChild('deptRevenueChart') deptRevenueChartRef!: ElementRef<HTMLCanvasElement>;

  private analyticsService = inject(AnalyticsService);
  private router = inject(Router);

  data: RevenueAnalytics | null = null;
  loading = true;
  error = '';

  private charts: Chart[] = [];

  ngOnInit(): void {
    this.loadData();
  }

  ngAfterViewInit(): void {}

  ngOnDestroy(): void {
    this.charts.forEach(c => c.destroy());
  }

  loadData(): void {
    this.loading = true;
    this.error = '';
    this.analyticsService.getRevenueAnalytics().subscribe({
      next: (res) => {
        this.data = res;
        this.loading = false;
        setTimeout(() => this.initCharts(), 100);
      },
      error: () => {
        this.error = 'Failed to load revenue analytics';
        this.loading = false;
      }
    });
  }

  goBack(): void {
    this.router.navigate(['/reports']);
  }

  exportPdf(): void { alert('Export coming soon'); }
  exportExcel(): void { alert('Export coming soon'); }
  exportCsv(): void { alert('Export coming soon'); }
  printReport(): void { window.print(); }

  private initCharts(): void {
    if (!this.data) return;
    this.initDailyTrendChart();
    this.initMonthlyTrendChart();
    this.initPaymentMethodsChart();
    this.initDeptRevenueChart();
  }

  private initDailyTrendChart(): void {
    if (!this.dailyTrendChartRef || !this.data) return;
    const labels = this.data.dailyTrend.map(d => d.date);
    const values = this.data.dailyTrend.map(d => d.amount);
    const chart = new Chart(this.dailyTrendChartRef.nativeElement, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Revenue',
          data: values,
          borderColor: '#198754',
          backgroundColor: 'rgba(25, 135, 84, 0.15)',
          fill: true,
          tension: 0.4,
          pointBackgroundColor: '#198754',
          pointBorderColor: '#fff',
          pointRadius: 3
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: { legend: { display: false } },
        scales: {
          x: { ticks: { color: 'rgba(255,255,255,0.5)', maxTicksLimit: 10 }, grid: { color: 'rgba(255,255,255,0.05)' } },
          y: { ticks: { color: 'rgba(255,255,255,0.5)' }, grid: { color: 'rgba(255,255,255,0.05)' } }
        }
      }
    });
    this.charts.push(chart);
  }

  private initMonthlyTrendChart(): void {
    if (!this.monthlyTrendChartRef || !this.data) return;
    const labels = this.data.monthlyTrend.map(m => m.month);
    const values = this.data.monthlyTrend.map(m => m.amount);
    const chart = new Chart(this.monthlyTrendChartRef.nativeElement, {
      type: 'bar',
      data: {
        labels,
        datasets: [{
          label: 'Revenue',
          data: values,
          backgroundColor: 'rgba(13, 110, 253, 0.7)',
          borderColor: '#0d6efd',
          borderWidth: 1,
          borderRadius: 6
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: { legend: { display: false } },
        scales: {
          x: { ticks: { color: 'rgba(255,255,255,0.5)' }, grid: { color: 'rgba(255,255,255,0.05)' } },
          y: { ticks: { color: 'rgba(255,255,255,0.5)' }, grid: { color: 'rgba(255,255,255,0.05)' } }
        }
      }
    });
    this.charts.push(chart);
  }

  private initPaymentMethodsChart(): void {
    if (!this.paymentMethodsChartRef || !this.data) return;
    const labels = this.data.paymentMethodDistribution.map(m => m.method);
    const values = this.data.paymentMethodDistribution.map(m => m.amount);
    const chart = new Chart(this.paymentMethodsChartRef.nativeElement, {
      type: 'pie',
      data: {
        labels,
        datasets: [{
          data: values,
          backgroundColor: [
            'rgba(13, 110, 253, 0.7)', 'rgba(25, 135, 84, 0.7)',
            'rgba(255, 193, 7, 0.7)', 'rgba(102, 16, 242, 0.7)',
            'rgba(220, 53, 69, 0.7)', 'rgba(13, 202, 240, 0.7)'
          ],
          borderColor: '#0a0e27',
          borderWidth: 2
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: { legend: { position: 'bottom', labels: { color: 'rgba(255,255,255,0.6)', padding: 16 } } }
      }
    });
    this.charts.push(chart);
  }

  private initDeptRevenueChart(): void {
    if (!this.deptRevenueChartRef || !this.data) return;
    const labels = this.data.revenueByDepartment.map(d => d.department);
    const values = this.data.revenueByDepartment.map(d => d.revenue);
    const chart = new Chart(this.deptRevenueChartRef.nativeElement, {
      type: 'bar',
      data: {
        labels,
        datasets: [{
          label: 'Revenue',
          data: values,
          backgroundColor: 'rgba(102, 16, 242, 0.7)',
          borderColor: '#6610f2',
          borderWidth: 1,
          borderRadius: 6
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: { legend: { display: false } },
        scales: {
          x: { ticks: { color: 'rgba(255,255,255,0.5)' }, grid: { color: 'rgba(255,255,255,0.05)' } },
          y: { ticks: { color: 'rgba(255,255,255,0.5)' }, grid: { color: 'rgba(255,255,255,0.05)' } }
        }
      }
    });
    this.charts.push(chart);
  }
}
